using UnityEngine;

namespace TimeToExplore.Rendering
{
    /// <summary>
    /// Puts a sky behind the orrery: the baked Milky Way band with procedural
    /// stars drawn by <see cref="RenderingShaders.Skybox"/>.
    ///
    /// The band is an equirectangular texture generated by
    /// <c>tools/generate_skybox.py</c>. Resolved stars are drawn in the shader
    /// rather than baked, because a baked star is the size of a texel — several
    /// screen pixels at the prototype's 60-degree field of view.
    ///
    /// The sky is fixed in the ecliptic frame: the camera orbits through it and
    /// the whole field turns with yaw and pitch. Travelling does
    /// not shift it, because stars are effectively at infinity; there is no
    /// parallax between Earth and Neptune, which is correct at the scale the
    /// prototype renders. There is no sidereal time either, so the band's
    /// azimuth is a composition choice, not a date.
    /// </summary>
    public sealed class SkyView : MonoBehaviour
    {
        /// <summary>Resources path of the generated band texture.</summary>
        public const string TextureResource = "Sky/milky_way";

        /// <summary>The band texture, or null when the asset is missing.</summary>
        public Texture2D Texture { get; private set; }

        /// <summary>The runtime skybox material, or null when the sky failed.</summary>
        public Material Material { get; private set; }

        /// <summary>True when the material exists, the camera is on Skybox, and RenderSettings points at it.</summary>
        public bool Applied { get; private set; }

        private Camera _camera;
        private CameraClearFlags _previousClearFlags;
        private Material _previousSkybox;
        private bool _restore;

        /// <summary>
        /// Load the texture and shader, build the material, and put the camera on
        /// it. A missing texture or shader leaves the camera on its clear colour
        /// and logs the regeneration command, so the orrery still runs.
        /// </summary>
        public void Initialise(Camera camera)
        {
            if (Applied) return;

            _camera = camera;
            Texture = Resources.Load<Texture2D>(TextureResource);
            Shader shader = Shader.Find(RenderingShaders.Skybox);
            if (!TryCreate(Texture, shader, out Material material))
            {
                Debug.LogWarning(
                    $"Skybox unavailable: texture '{TextureResource}' or shader " +
                    $"'{RenderingShaders.Skybox}' is missing. The background stays " +
                    "black. Run tools/generate_skybox.py to recreate the texture.");
                return;
            }

            Material = material;

            if (camera != null)
            {
                _previousClearFlags = camera.clearFlags;
                camera.clearFlags = CameraClearFlags.Skybox;
            }

            _previousSkybox = RenderSettings.skybox;
            RenderSettings.skybox = Material;
            _restore = true;
            Applied = true;
        }

        /// <summary>
        /// Build the skybox material. Public so the EditMode suite can check the
        /// wiring without touching the scene's render settings.
        /// </summary>
        public static bool TryCreate(Texture2D texture, Shader shader, out Material material)
        {
            material = null;
            if (texture == null || shader == null) return false;

            material = new Material(shader) { name = "Milky Way Skybox" };
            material.SetTexture("_MainTex", texture);
            material.SetFloat("_BandGain", 1f);
            material.SetFloat("_StarGain", 1f);
            return true;
        }

        /// <summary>
        /// Undo <see cref="Initialise"/>: restore the previous skybox and clear
        /// flags and release the material. Idempotent.
        ///
        /// <see cref="OnDestroy"/> calls this, but EditMode tests must call it
        /// themselves: Unity does not deliver <c>OnDestroy</c> to a plain
        /// MonoBehaviour that is created and destroyed in edit mode.
        /// </summary>
        public void Remove()
        {
            if (!_restore) return;
            _restore = false;

            RenderSettings.skybox = _previousSkybox;
            if (_camera != null) _camera.clearFlags = _previousClearFlags;
            if (Material != null)
            {
                if (Application.isPlaying) Destroy(Material);
                else DestroyImmediate(Material);
            }

            Material = null;
            Applied = false;
        }

        private void OnDestroy()
        {
            Remove();
        }
    }
}
